import { jsPDF } from 'jspdf';

export function generateCertificate({ deviceType, method, timestamp, certificateId }) {
    const doc = new jsPDF();

    // Colors
    const greenColor = [34, 197, 94]; // Green-500
    const grayColor = [107, 114, 128]; // Gray-500

    // Header Section
    doc.setFillColor(34, 197, 94);
    doc.rect(0, 0, 210, 40, 'F');

    // Logo/Title
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(28);
    doc.setFont('helvetica', 'bold');
    doc.text('EcoWIPE', 105, 20, { align: 'center' });

    doc.setFontSize(12);
    doc.setFont('helvetica', 'normal');
    doc.text('Data Sanitization Certificate', 105, 30, { align: 'center' });

    // Certificate Body
    doc.setTextColor(0, 0, 0);
    doc.setFontSize(18);
    doc.setFont('helvetica', 'bold');
    doc.text('CERTIFICATE OF DATA DESTRUCTION', 105, 60, { align: 'center' });

    // Decorative line
    doc.setDrawColor(...greenColor);
    doc.setLineWidth(0.5);
    doc.line(40, 65, 170, 65);

    // Certificate ID
    doc.setFontSize(10);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(...grayColor);
    doc.text(`Certificate ID: ${certificateId}`, 105, 75, { align: 'center' });

    // Main Content
    doc.setTextColor(0, 0, 0);
    doc.setFontSize(11);
    doc.setFont('helvetica', 'normal');

    const contentY = 90;
    doc.text('This is to certify that the following device has been securely wiped:', 20, contentY);

    // Details Box
    doc.setDrawColor(...grayColor);
    doc.setLineWidth(0.3);
    doc.rect(20, contentY + 5, 170, 50);

    doc.setFont('helvetica', 'bold');
    doc.text('Device Type:', 30, contentY + 15);
    doc.setFont('helvetica', 'normal');
    doc.text(deviceType.toUpperCase(), 70, contentY + 15);

    doc.setFont('helvetica', 'bold');
    doc.text('Wipe Method:', 30, contentY + 25);
    doc.setFont('helvetica', 'normal');
    const methodName = method.charAt(0).toUpperCase() + method.slice(1);
    const methodDetails = method === 'military' ? `${methodName} (DoD 5220.22-M)` :
        method === 'deep' ? `${methodName} (3-pass)` :
            `${methodName} (Single pass)`;
    doc.text(methodDetails, 70, contentY + 25);

    doc.setFont('helvetica', 'bold');
    doc.text('Date & Time:', 30, contentY + 35);
    doc.setFont('helvetica', 'normal');
    doc.text(new Date(timestamp).toLocaleString(), 70, contentY + 35);

    doc.setFont('helvetica', 'bold');
    doc.text('Status:', 30, contentY + 45);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(...greenColor);
    doc.text('✓ COMPLETED SUCCESSFULLY', 70, contentY + 45);

    // Compliance Statement
    doc.setTextColor(0, 0, 0);
    doc.setFontSize(10);
    doc.setFont('helvetica', 'italic');
    doc.text('This wipe operation meets industry standards for data sanitization.', 105, contentY + 65, { align: 'center' });
    doc.text('All data on the device has been permanently and irreversibly destroyed.', 105, contentY + 72, { align: 'center' });

    // Verification Section
    doc.setFontSize(9);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(...grayColor);
    doc.text('Verification:', 20, contentY + 90);
    doc.text(`Verify this certificate at: https://ecowipe.com/verify/${certificateId}`, 20, contentY + 97);

    // Footer
    doc.setDrawColor(...greenColor);
    doc.setLineWidth(0.5);
    doc.line(20, 260, 190, 260);

    doc.setFontSize(8);
    doc.setTextColor(...grayColor);
    doc.text('EcoWIPE - Secure Data Sanitization Platform', 105, 270, { align: 'center' });
    doc.text('Generated automatically by EcoWIPE Desktop Agent', 105, 276, { align: 'center' });
    doc.text(`Certificate issued: ${new Date(timestamp).toISOString()}`, 105, 282, { align: 'center' });

    // Green stamp
    doc.setFillColor(34, 197, 94, 20);
    doc.circle(170, 240, 15, 'F');
    doc.setTextColor(...greenColor);
    doc.setFontSize(10);
    doc.setFont('helvetica', 'bold');
    doc.text('VERIFIED', 170, 238, { align: 'center' });
    doc.text('SECURE', 170, 244, { align: 'center' });

    // Save the PDF
    doc.save(`EcoWIPE_Certificate_${certificateId}.pdf`);

    return certificateId;
}

// Generate unique certificate ID
export function generateCertificateId() {
    const timestamp = Date.now().toString(36);
    const random = Math.random().toString(36).substring(2, 8);
    return `ECW-${timestamp}-${random}`.toUpperCase();
}

/**
 * Generates a rich PDF certificate from a scanned EcoWIPE QR code JSON payload.
 * @param {Object} options
 * @param {Object} options.data      – The parsed JSON from the EcoWIPE QR code
 * @param {string} options.userName  – The logged-in user's display name
 */
export function generateCertificateFromQR({ data, userName }) {
    const doc = new jsPDF();
    const green = [34, 197, 94];
    const emerald = [16, 185, 129];
    const gray = [107, 114, 128];
    const dark = [55, 65, 81];
    const light = [243, 244, 246];

    const certId = `ECW-${(data.timestamp || Date.now()).toString(36).toUpperCase()}-${(data.drive_serial || 'UNKNOWN').slice(-6)}`;

    // ── Green header ──────────────────────────────────────────────
    doc.setFillColor(...green);
    doc.rect(0, 0, 210, 45, 'F');
    doc.setFillColor(...emerald);
    doc.rect(140, 0, 70, 45, 'F');
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(30); doc.setFont('helvetica', 'bold');
    doc.text('EcoWIPE', 20, 22);
    doc.setFontSize(11); doc.setFont('helvetica', 'normal');
    doc.text('Data Sanitization Certificate', 20, 32);
    doc.setFontSize(9); doc.setTextColor(200, 255, 200);
    doc.text(`Cert ID: ${certId}`, 190, 12, { align: 'right' });
    doc.text(`Schema: ${data.schema || 'EcoWIPE-v2'}`, 190, 20, { align: 'right' });

    // ── Title ─────────────────────────────────────────────────────
    doc.setTextColor(...dark); doc.setFontSize(15); doc.setFont('helvetica', 'bold');
    doc.text('CERTIFICATE OF DATA DESTRUCTION', 105, 58, { align: 'center' });
    doc.setDrawColor(...green); doc.setLineWidth(0.8); doc.line(30, 62, 180, 62);

    // ── Issued To ─────────────────────────────────────────────────
    doc.setFontSize(9); doc.setFont('helvetica', 'normal'); doc.setTextColor(...gray);
    doc.text('This certifies that the following wipe operation was performed by:', 105, 70, { align: 'center' });
    doc.setFillColor(...light); doc.roundedRect(30, 73, 150, 13, 2, 2, 'F');
    doc.setFontSize(12); doc.setFont('helvetica', 'bold'); doc.setTextColor(...dark);
    doc.text(userName || 'EcoWIPE User', 105, 82, { align: 'center' });

    const row = (label, value, x, y) => {
        doc.setFont('helvetica', 'bold'); doc.setTextColor(...gray); doc.setFontSize(7.5);
        doc.text(label, x, y);
        doc.setFont('helvetica', 'normal'); doc.setTextColor(...dark); doc.setFontSize(9);
        doc.text(String(value || 'N/A'), x, y + 5);
    };

    // ── Device Details ────────────────────────────────────────────
    let y = 95;
    doc.setFontSize(8); doc.setFont('helvetica', 'bold'); doc.setTextColor(...green);
    doc.text('DEVICE INFORMATION', 20, y);
    doc.setDrawColor(...emerald); doc.setLineWidth(0.3); doc.line(20, y + 2, 95, y + 2);
    doc.setFillColor(...light); doc.rect(20, y + 5, 170, 40, 'F');
    row('Drive Model', data.drive_model, 25, y + 13);
    row('Serial Number', data.drive_serial, 110, y + 13);
    row('Device Path', data.drive_path, 25, y + 26);
    row('Capacity', data.drive_size, 110, y + 26);
    row('Machine ID', data.machine_id, 25, y + 39);

    // ── Wipe Details ──────────────────────────────────────────────
    y += 52;
    doc.setFontSize(8); doc.setFont('helvetica', 'bold'); doc.setTextColor(...green);
    doc.text('ERASURE DETAILS', 20, y);
    doc.line(20, y + 2, 85, y + 2);
    doc.setFillColor(...light); doc.rect(20, y + 5, 170, 28, 'F');
    row('Wipe Method', data.wipe_method, 25, y + 13);
    row('NIST Standard', data.nist_standard, 95, y + 13);
    row('Wipe Passes', `${data.wipe_passes} pass(es)`, 160, y + 13);
    row('Date & Time', data.datetime ? new Date(data.datetime).toLocaleString() : 'N/A', 25, y + 26);

    // ── Status Banner ─────────────────────────────────────────────
    y += 40;
    const ok = data.status === 'SUCCESS';
    doc.setFillColor(ok ? 220 : 254, ok ? 252 : 202, ok ? 231 : 202);
    doc.rect(20, y, 170, 16, 'F');
    doc.setDrawColor(ok ? 34 : 220, ok ? 197 : 38, ok ? 94 : 38);
    doc.setLineWidth(0.5); doc.rect(20, y, 170, 16, 'S');
    doc.setFontSize(11); doc.setFont('helvetica', 'bold');
    doc.setTextColor(ok ? 21 : 153, ok ? 128 : 27, ok ? 61 : 27);
    doc.text(ok ? '✓ WIPE COMPLETED SUCCESSFULLY' : '✗ WIPE FAILED', 105, y + 10, { align: 'center' });

    // ── Hash Box ──────────────────────────────────────────────────
    y += 23;
    doc.setFontSize(8); doc.setFont('helvetica', 'bold'); doc.setTextColor(...green);
    doc.text('CRYPTOGRAPHIC VERIFICATION', 20, y);
    doc.line(20, y + 2, 115, y + 2);
    doc.setFillColor(17, 24, 39); doc.rect(20, y + 5, 170, 22, 'F');
    doc.setFont('helvetica', 'normal'); doc.setTextColor(134, 239, 172); doc.setFontSize(7.5);
    doc.text(`Verification Hash: ${data.verification || 'N/A'}`, 25, y + 13);
    doc.text(`Record Hash:       ${data.record_hash || 'N/A'}`, 25, y + 20);

    // ── Footer ────────────────────────────────────────────────────
    doc.setDrawColor(...green); doc.setLineWidth(0.5); doc.line(20, 268, 190, 268);
    doc.setFontSize(8); doc.setFont('helvetica', 'normal'); doc.setTextColor(...gray);
    doc.text('EcoWIPE — Secure Data Sanitization Platform', 105, 274, { align: 'center' });
    doc.text(`Certificate generated: ${new Date().toISOString()}`, 105, 280, { align: 'center' });
    doc.text('ecowipe.github.io/e-waste', 105, 286, { align: 'center' });

    // Verified stamp
    doc.setFillColor(34, 197, 94, 25); doc.circle(175, 258, 13, 'F');
    doc.setDrawColor(...green); doc.setLineWidth(0.8); doc.circle(175, 258, 13, 'S');
    doc.setTextColor(...green); doc.setFontSize(7); doc.setFont('helvetica', 'bold');
    doc.text('AI', 175, 254, { align: 'center' });
    doc.text('VERIFIED', 175, 259, { align: 'center' });
    doc.text('SECURE', 175, 264, { align: 'center' });

    doc.save(`EcoWIPE_Certificate_${certId}.pdf`);
    return certId;
}
