import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { Link, useNavigate } from "react-router-dom";
import DownloadOSSection from "../components/common/DownloadOSSection";
import { Card, CardContent, CardHeader, CardTitle } from "../components/ui/card";
import { Badge } from "../components/ui/badge";
import { Button } from "../components/ui/button";
import SystemDiagnostics from "../components/dashboard/SystemDiagnostics";
import {
  Award,
  Shield,
  Leaf,
  Download,
  Calendar,
  HardDrive,
  TrendingUp,
  Lock,
  Recycle,
  ArrowRight,
  Terminal,
  Cpu,
  QrCode,
  CheckCircle,
  FileText
} from "lucide-react";
import { WipeRecord } from "../entities/WipeRecord";
import { User } from "../entities/User";
import { format } from "date-fns";
import { useAuth } from "../context/AuthContext";
// import { HoverCard, HoverCardContent, HoverCardTrigger } from "../components/ui/hover-card";


const BADGE_DEFINITIONS = {
  GREEN_SHIELD: { name: "Green Shield", description: "Completed your first secure wipe!", icon: Shield, color: "green" },
  DATA_GUARDIAN: { name: "Data Guardian", description: "Wiped 5 devices securely.", icon: Lock, color: "blue" },
  ECO_WARRIOR: { name: "Eco Warrior", description: "Wiped 10 devices, saving the planet!", icon: Leaf, color: "emerald" },
  RECYCLING_CHAMPION: { name: "Recycling Champion", description: "Wiped over 500GB of data.", icon: Recycle, color: "purple" },
};

const BadgeDisplay = ({ badgeKey }) => {
  const badge = BADGE_DEFINITIONS[badgeKey];
  if (!badge) return null;

  const Icon = badge.icon;
  const colorClasses = {
    green: "bg-green-100 text-green-600",
    blue: "bg-blue-100 text-blue-600",
    emerald: "bg-emerald-100 text-emerald-600",
    purple: "bg-purple-100 text-purple-600",
  };
  const colorClass = colorClasses[badge.color] || "bg-gray-100 text-gray-600";

  return (
    <div title={`${badge.name}: ${badge.description}`} className="flex flex-col items-center gap-2">
      <motion.div
        whileHover={{ scale: 1.1, rotate: 5 }}
        className={`w-16 h-16 rounded-full flex items-center justify-center cursor-pointer ${colorClass} border-2 border-white shadow-md`}
      >
        <Icon className="w-8 h-8" />
      </motion.div>
      <span className="text-xs font-medium text-gray-600">{badge.name}</span>
    </div>
  );
}

const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:5001';

export default function DashboardPage() {
  const [wipeRecords, setWipeRecords] = useState([]);
  const [vaultCerts, setVaultCerts] = useState([]);
  const [offlineStats, setOfflineStats] = useState({ points: 0, devices: 0, gb: 0, badges: [] });
  const { user, token } = useAuth();
  const [isLoading, setIsLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    loadData();
  }, [user]);

  const loadData = async () => {
    setIsLoading(true);
    try {
      const records = await WipeRecord.list("-created_date");
      setWipeRecords(records);
    } catch (error) {
      console.error("Error loading wipe records:", error);
    }
    // Load Certificate Vault from localStorage
    try {
      const vaultData = JSON.parse(localStorage.getItem('ecowipe_cert_vault') || '[]');
      setVaultCerts(vaultData);

      // Calculate offline stats
      let pts = 0, devs = vaultData.length, gb = 0;
      vaultData.forEach(c => {
        pts += (c.eco_points_awarded || 0);
        if (c.drive_size) {
          const num = parseFloat(c.drive_size);
          if (!isNaN(num)) {
            if (String(c.drive_size).toUpperCase().includes('T')) gb += (num * 1024);
            else if (String(c.drive_size).toUpperCase().includes('M')) gb += (num / 1024);
            else gb += num;
          }
        }
      });
      setOfflineStats({ points: pts, devices: devs, gb });

    } catch (err) {
      setVaultCerts([]);
    }
    setIsLoading(false);
  };

  const getMethodColor = (method) => {
    return {
      quick: "bg-blue-100 text-blue-800",
      deep: "bg-purple-100 text-purple-800",
      military: "bg-red-100 text-red-800"
    }[method] || "bg-gray-100 text-gray-800";
  };

  const getDeviceIcon = (deviceType) => {
    // You can expand this with more specific icons
    return HardDrive;
  };

  const totalPoints = (user?.total_eco_points || 0) + offlineStats.points;
  const totalDevs = (user?.total_devices_wiped || 0) + offlineStats.devices;
  const totalGb = (user?.total_data_wiped_gb || 0) + offlineStats.gb;

  // Compute offline badges logic
  const computedBadgesSet = new Set(user?.eco_badges || []);
  if (totalDevs >= 1) computedBadgesSet.add('GREEN_SHIELD');
  if (totalDevs >= 5) computedBadgesSet.add('DATA_GUARDIAN');
  if (totalDevs >= 10) computedBadgesSet.add('ECO_WARRIOR');
  if (totalGb >= 500) computedBadgesSet.add('RECYCLING_CHAMPION');
  const allBadges = Array.from(computedBadgesSet);

  const stats = [
    {
      title: "Total Eco Points",
      value: totalPoints,
      icon: Award,
      color: "from-green-500 to-emerald-500",
      change: "Auto-updating"
    },
    {
      title: "Devices Wiped",
      value: totalDevs,
      icon: Shield,
      color: "from-blue-500 to-cyan-500",
      change: "All secure"
    },
    {
      title: "Data Wiped",
      value: `${totalGb.toFixed(0)} GB`,
      icon: HardDrive,
      color: "from-purple-500 to-indigo-500",
      change: "Permanently deleted"
    },
    {
      title: "CO₂ Saved",
      value: `${(totalGb * 0.5).toFixed(1)} kg`,
      icon: Leaf,
      color: "from-emerald-500 to-green-500",
      change: "Environmental impact"
    }
  ];

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-green-50/30 to-blue-50/20 p-6">
      <div className="max-w-7xl mx-auto">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="mb-8"
        >
          <h1 className="text-4xl font-bold text-gray-900 mb-2">
            Your EcoWipe Dashboard
          </h1>
          <p className="text-gray-600 text-lg">
            Track your secure wiping activity and environmental impact
          </p>
        </motion.div>

        {/* System Diagnostics Module */}
        <SystemDiagnostics />

        {/* Stats Cards */}
        <div className="grid grid-cols-2 md:grid-cols-2 lg:grid-cols-4 gap-3 md:gap-6 mb-8">
          {stats.map((stat, index) => (
            <motion.div
              key={stat.title}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: index * 0.1 }}
            >
              <Card className="relative overflow-hidden hover:shadow-xl transition-all duration-300">
                <div className={`absolute top-0 right-0 w-32 h-32 bg-gradient-to-br ${stat.color} opacity-10 rounded-full transform translate-x-8 -translate-y-8`} />
                <CardHeader className="pb-3">
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="text-sm font-medium text-gray-600">{stat.title}</p>
                      <p className="text-3xl font-bold text-gray-900 mt-1">{stat.value}</p>
                    </div>
                    <div className={`w-12 h-12 bg-gradient-to-br ${stat.color} rounded-xl flex items-center justify-center shadow-lg`}>
                      <stat.icon className="w-6 h-6 text-white" />
                    </div>
                  </div>
                  <div className="flex items-center gap-1 text-sm">
                    <TrendingUp className="w-4 h-4 text-green-500" />
                    <span className="text-green-600 font-medium">{stat.change}</span>
                  </div>
                </CardHeader>
              </Card>
            </motion.div>
          ))}
        </div>

        {/* Quick Actions / Execute Wipe */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
          className="mb-8 hidden md:block" // Hidden on small screens if you want, but better to keep
        >
          <Card className="bg-gradient-to-r from-slate-900 to-slate-800 text-white shadow-xl overflow-hidden relative border-0">
            <div className="absolute right-0 top-0 opacity-10 pointer-events-none">
              <Terminal className="w-64 h-64 -mt-10 -mr-10" />
            </div>
            <CardContent className="p-8 md:p-12 relative z-10 flex flex-col md:flex-row items-center justify-between gap-8">
              <div className="max-w-xl">
                <h3 className="text-3xl font-bold mb-4">Start New Data Destruction</h3>
                <p className="text-slate-300 text-lg mb-0">
                  Execute a secure data wipe using our Web Simulator. This interface mirrors the Desktop Agent experience for selecting devices, methods, and generating verifiable certificates.
                </p>
              </div>
              <Link to="/wipe">
                <Button className="bg-green-500 hover:bg-green-600 text-white shadow-lg hover:shadow-green-500/20 px-8 py-6 text-xl rounded-xl whitespace-nowrap group transition-all duration-300">
                  Launch Web Simulator
                  <ArrowRight className="w-6 h-6 ml-2 group-hover:translate-x-1 transition-transform" />
                </Button>
              </Link>
            </CardContent>
          </Card>
        </motion.div>

        {/* Unified Downloads Hub */}
        <div className="mb-8">
          <DownloadOSSection />
        </div>

        {/* Badges Section */}
        {allBadges.length > 0 && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.3 }}
            className="mb-8"
          >
            <Card className="shadow-lg border-0 bg-white/80 backdrop-blur-sm">
              <CardHeader>
                <CardTitle className="text-2xl font-bold">Your Eco-Badges</CardTitle>
              </CardHeader>
              <CardContent className="flex flex-wrap gap-4">
                {allBadges.map(badgeKey => (
                  <BadgeDisplay key={badgeKey} badgeKey={badgeKey} />
                ))}
              </CardContent>
            </Card>
          </motion.div>
        )}

        {/* Certificate Vault */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.35 }}
          className="mb-8"
        >
          <Card className="shadow-xl border-0 bg-white/80 backdrop-blur-sm overflow-hidden">
            <CardHeader>
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <div className="w-9 h-9 bg-gradient-to-br from-green-500 to-emerald-600 rounded-xl flex items-center justify-center">
                    <FileText className="w-5 h-5 text-white" />
                  </div>
                  <CardTitle className="text-2xl font-bold">Certificate Vault</CardTitle>
                </div>
                <Link to="/scan">
                  <button className="flex items-center gap-2 text-sm font-semibold text-green-700 bg-green-50 border border-green-200 px-4 py-2 rounded-xl hover:bg-green-100 transition-all">
                    <QrCode className="w-4 h-4" />
                    Scan New QR
                  </button>
                </Link>
              </div>
            </CardHeader>
            <CardContent>
              {vaultCerts.length === 0 ? (
                <div className="text-center py-10">
                  <QrCode className="w-14 h-14 text-gray-300 mx-auto mb-3" />
                  <h3 className="text-lg font-semibold text-gray-500 mb-1">No certificates yet</h3>
                  <p className="text-gray-400 text-sm mb-4">Scan a QR code from the EcoWIPE ISO or Desktop Agent to claim your first certificate.</p>
                  <Link to="/scan">
                    <button className="bg-gradient-to-r from-green-600 to-emerald-600 text-white px-6 py-2.5 rounded-xl text-sm font-semibold shadow hover:shadow-md transition-all">
                      Scan QR Code
                    </button>
                  </Link>
                </div>
              ) : (
                <div className="space-y-3">
                  {vaultCerts.map((cert, idx) => (
                    <motion.div
                      key={cert.id || cert._id || idx}
                      initial={{ opacity: 0, x: -20 }}
                      animate={{ opacity: 1, x: 0 }}
                      transition={{ delay: idx * 0.05 }}
                      className="flex items-center gap-4 p-4 bg-gradient-to-r from-green-50 to-emerald-50 rounded-xl border border-green-100 hover:shadow-md transition-all"
                    >
                      <div className="w-12 h-12 bg-gradient-to-br from-green-100 to-emerald-100 rounded-xl flex items-center justify-center shrink-0">
                        <CheckCircle className="w-6 h-6 text-green-600" />
                      </div>
                      <div className="flex-1 min-w-0">
                        <h4 className="font-semibold text-gray-900 truncate">{cert.drive_model || 'Drive'}</h4>
                        <div className="flex flex-wrap items-center gap-2 mt-0.5">
                          <span className="text-xs bg-green-100 text-green-700 px-2 py-0.5 rounded-full font-medium">{cert.wipe_method}</span>
                          <span className="text-xs text-gray-500">{cert.drive_size}</span>
                          <span className="text-xs text-gray-400">&bull;</span>
                          <span className="text-xs text-gray-500 flex items-center gap-1">
                            <Calendar className="w-3 h-3" />
                            {new Date(cert.claimed_at).toLocaleDateString()}
                          </span>
                        </div>
                        <p className="text-xs text-gray-400 font-mono mt-0.5 truncate">S/N: {cert.drive_serial}</p>
                      </div>
                      <div className="text-right shrink-0">
                        <div className="flex items-center gap-1 text-green-600 font-semibold">
                          <Award className="w-4 h-4" />
                          <span>+{cert.eco_points_awarded}</span>
                        </div>
                        <span className="text-xs text-gray-400">pts</span>
                      </div>
                    </motion.div>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.4 }}
        >
          <Card className="shadow-xl border-0 bg-white/80 backdrop-blur-sm">
            <CardHeader>
              <div className="flex items-center justify-between">
                <CardTitle className="text-2xl font-bold">Recent Wipe Activity</CardTitle>
                <Button variant="outline" className="gap-2">
                  <Download className="w-4 h-4" />
                  Export History
                </Button>
              </div>
            </CardHeader>
            <CardContent>
              {isLoading ? (
                <div className="space-y-4">
                  {[...Array(3)].map((_, i) => (
                    <div key={i} className="animate-pulse">
                      <div className="flex items-center gap-4 p-4 bg-gray-100 rounded-xl">
                        <div className="w-12 h-12 bg-gray-200 rounded-xl" />
                        <div className="flex-1 space-y-2">
                          <div className="h-4 bg-gray-200 rounded w-1/3" />
                          <div className="h-3 bg-gray-200 rounded w-1/2" />
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              ) : wipeRecords.length === 0 ? (
                <div className="text-center py-12">
                  <Shield className="w-16 h-16 text-gray-400 mx-auto mb-4" />
                  <h3 className="text-xl font-semibold text-gray-600 mb-2">
                    No wipe records yet
                  </h3>
                  <p className="text-gray-500">
                    Start your first secure wipe to see your activity here
                  </p>
                </div>
              ) : (
                <div className="space-y-4">
                  {wipeRecords.map((record, index) => {
                    const DeviceIcon = getDeviceIcon(record.device_type);
                    return (
                      <motion.div
                        key={record.id}
                        initial={{ opacity: 0, x: -20 }}
                        animate={{ opacity: 1, x: 0 }}
                        transition={{ delay: index * 0.05 }}
                        className="flex items-center gap-4 p-4 bg-gradient-to-r from-white to-gray-50 rounded-xl border border-gray-100 hover:shadow-lg transition-all duration-200"
                      >
                        <div className="w-12 h-12 bg-gradient-to-br from-gray-100 to-gray-200 rounded-xl flex items-center justify-center">
                          <DeviceIcon className="w-6 h-6 text-gray-600" />
                        </div>

                        <div className="flex-1">
                          <div className="flex items-center gap-2 mb-1">
                            <h4 className="font-semibold text-gray-900 capitalize">
                              {record.device_type} Device
                            </h4>
                            <Badge className={getMethodColor(record.wipe_method)}>
                              {record.wipe_method} wipe
                            </Badge>
                            <Badge variant="outline">
                              {record.operating_system}
                            </Badge>
                          </div>
                          <div className="flex items-center gap-4 text-sm text-gray-500">
                            <span className="flex items-center gap-1">
                              <Calendar className="w-3 h-3" />
                              {format(new Date(record.created_date), "MMM d, yyyy 'at' h:mm a")}
                            </span>
                            {record.device_size_gb > 0 && (
                              <span>{record.device_size_gb} GB wiped</span>
                            )}
                          </div>
                        </div>

                        <div className="text-right">
                          <div className="flex items-center gap-1 text-green-600 font-semibold mb-1">
                            <Award className="w-4 h-4" />
                            +{record.eco_points} points
                          </div>
                          <Badge
                            variant={record.status === 'completed' ? 'default' : 'secondary'}
                            className={record.status === 'completed' ? 'bg-green-100 text-green-800' : ''}
                          >
                            {record.status}
                          </Badge>
                        </div>
                      </motion.div>
                    );
                  })}
                </div>
              )}
            </CardContent>
          </Card>
        </motion.div>
      </div>
    </div>
  );
}